from flask import Flask, request
import os

app = Flask(__name__)

@app.route('/find')
def find():
    rootdir = request.args.get('path')
    output = []

    for root, subdirs, files in os.walk(rootdir):
        for file in files:
            fullpath = os.path.join(root, file)
            if os.path.isfile(fullpath):
                output.append(fullpath)

    return str(output)

app.run()

